#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    char key[32];
    int value;
    struct Node *next;
} Node;

typedef struct {
    size_t cap;
    Node **buckets;
} HashTable;

unsigned long hash(const char *s) {
    unsigned long h = 5381;
    int c;
    while ((c = (unsigned char)*s++)) h = h * 33 + c;
    return h;
}

HashTable *ht_create(size_t cap) {
    HashTable *ht = malloc(sizeof *ht);
    ht->cap = cap;
    ht->buckets = calloc(cap, sizeof(Node *));
    return ht;
}

void ht_put(HashTable *ht, const char *key, int value) {
    size_t idx = hash(key) % ht->cap;
    for (Node *p = ht->buckets[idx]; p; p = p->next) {
        if (strcmp(p->key, key) == 0) {
            p->value = value;
            printf("update %-4s = %d  -> o [%zu]\n", key, value, idx);
            return;
        }
    }
    printf("insert %-4s = %d  -> o [%zu]\n", key, value, idx);
    Node *n = malloc(sizeof *n);
    strcpy(n->key, key);
    n->value = value;
    n->next = ht->buckets[idx];
    ht->buckets[idx] = n;
}

void ht_print(HashTable *ht) {
    for (size_t i = 0; i < ht->cap; i++) {
        printf("[%zu]", i);
        for (Node *p = ht->buckets[i]; p; p = p->next)
            printf(" %s=%d", p->key, p->value);
        printf("\n");
    }
}

void ht_free(HashTable *ht) {
    for (size_t i = 0; i < ht->cap; i++) {
        Node *p = ht->buckets[i];
        while (p) {
            Node *next = p->next;
            free(p);
            p = next;
        }
    }
    free(ht->buckets);
    free(ht);
}

int main(void) {
    HashTable *ht = ht_create(8);
    ht_put(ht, "meo", 1);
    ht_put(ht, "bo", 2);
    ht_put(ht, "ga", 3);
    ht_put(ht, "meo", 9);
    printf("\n");
    ht_print(ht);
    ht_free(ht);
    return 0;
}
